const HTML_B64 = "";

export default {
  async fetch(request) {
    const bytes = Uint8Array.from(atob(HTML_B64), c => c.charCodeAt(0));
    const html = new TextDecoder("utf-8").decode(bytes);
    return new Response(html, {
      headers: { "content-type": "text/html;charset=UTF-8" },
    });
  },
};
